package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.common.ApiException;import com.bocsoft.sqleditor.config.SqlEditorProperties;import java.sql.Statement;import java.util.concurrent.CountDownLatch;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ExecutionRegistryTest {@Test void enforcesPerUserQuotaAndCountsBySource(){SqlEditorProperties p=new SqlEditorProperties();p.getExecution().setMaxConcurrentGlobal(2);p.getExecution().setMaxConcurrentPerUser(1);ExecutionRegistry registry=new ExecutionRegistry(p);registry.acquire("one","user","source");assertThat(registry.count("source")).isEqualTo(1);assertThatThrownBy(()->registry.acquire("two","user","source")).isInstanceOf(ApiException.class).extracting("code").isEqualTo("EXECUTION_LIMIT_EXCEEDED");registry.finish("one");assertThat(registry.count("source")).isZero();}@Test void cancelsOnlyTheOwningUsersStatement()throws Exception{SqlEditorProperties p=new SqlEditorProperties();ExecutionRegistry registry=new ExecutionRegistry(p);CountDownLatch acquired=new CountDownLatch(1),release=new CountDownLatch(1);Thread owner=new Thread(()->{registry.acquire("id","owner","source");acquired.countDown();try{release.await();}catch(InterruptedException ignored){}});owner.start();acquired.await();Statement statement=mock(Statement.class);registry.bind("id",statement);assertThat(registry.cancel("id","other")).isFalse();assertThat(registry.cancel("id","owner")).isTrue();verify(statement).cancel();release.countDown();owner.join();registry.finish("id");}}
